/* UVG · propuesta aprobada. La decoración no contiene acciones ni datos. */
:root{
 --ink:#191c19;--muted:#53624f;--green:#008d36;--green2:#00652b;
 --lime:#b0eb08;--paper:#f6f7ef;--line:#d6dfcf;--purple:#5145b5;
 --radius:12px;font-family:"Segoe UI",Arial,sans-serif;
}
body{background:var(--paper)}
h1,h2,h3{font-weight:850;letter-spacing:-.04em}
.ui-icon{width:24px;height:24px;display:block;flex-shrink:0}
button,.button{border:2px solid var(--ink);border-radius:6px;background:var(--lime);color:var(--ink);padding:11px 17px;box-shadow:3px 3px 0 var(--ink);font-weight:800;transition:background .15s,transform .15s,box-shadow .15s}
button:hover,.button:hover{background:#c1f733;box-shadow:1px 1px 0 var(--ink);transform:translate(1px,1px)}
button:disabled{transform:none}
.secondary{background:white;color:var(--ink)}.secondary:hover{background:#f1f9df}
.danger{background:#c22c35;color:white}.danger:hover{background:#a1212a}
.text-button{background:transparent;color:var(--green2);border:0;box-shadow:none;padding:8px 10px}
.text-button:hover{background:#e9f6d4;box-shadow:none;transform:none}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid var(--purple);outline-offset:4px}
.eyebrow{font-size:.65rem;font-weight:850;letter-spacing:1.7px}
.logo{display:flex;align-items:center;flex-wrap:wrap;gap:15px;text-decoration:none;color:var(--ink);letter-spacing:0}
.brand-lockup{display:flex;flex-direction:column;gap:7px;max-width:100%}
.uvg-logo{display:block;width:245px;height:53px;background:var(--uvg-logo) left center/contain no-repeat;max-width:100%}
.brand-slogan{font-size:.68rem;line-height:1.3;color:#263e2b;font-weight:700;letter-spacing:0}
.brand-name{display:block;font-size:1.2rem;font-weight:850;border-left:5px solid var(--lime);padding-left:10px;line-height:1.15}
.logo .brand-name small{font-size:.53rem;letter-spacing:1.7px;margin-top:5px;color:var(--muted)}
/* Curvas e íconos vectoriales. */
.login{background:#b0eb08;isolation:isolate;position:relative;overflow:hidden;padding:28px 5vw 20px}
.login::before{content:"";position:absolute;inset:0;z-index:-1;background-image:var(--uvg-waves);background-size:cover;pointer-events:none}
.login>.logo{align-self:flex-start;background:white;padding:13px 19px;border:2px solid var(--ink);border-radius:6px;box-shadow:5px 5px 0 var(--ink);max-width:100%;gap:17px}
.login>.logo .brand-name{border-left:2px solid var(--ink);padding-left:16px}
.login-columns{max-width:1200px;grid-template-columns:minmax(0,1.15fr) minmax(350px,1fr);gap:6vw;padding:35px 0;align-items:center}
.login-story{position:relative;min-width:0;padding-bottom:230px}
.login-story>.eyebrow{display:inline-block;color:white;background:var(--ink);padding:9px 13px;transform:rotate(-2deg);margin-bottom:19px;max-width:100%}
.login-story h1,.hero h1,.page-heading h1{font-family:"Arial Black","Segoe UI",Arial,sans-serif;font-weight:950;color:white;letter-spacing:-.055em;line-height:1.08;-webkit-text-stroke:1px var(--ink);paint-order:stroke fill;text-shadow:3px 4px 0 var(--ink)}
.login-story h1{font-size:clamp(2.9rem,4.2vw,4rem);max-width:550px}
.login-story .intro{font-size:1rem;color:#243313;font-weight:550;max-width:450px;margin-bottom:20px}
.steps{border-top:2px solid #548315;padding-top:18px;margin-top:24px;gap:13px}
.step{color:#263719;font-size:.75rem;font-weight:600}.step b{color:var(--ink);font-size:1.6rem;font-weight:900;margin-bottom:4px}
.login-story>.mascot-scene{position:absolute;right:12%;bottom:-8px;width:230px;height:240px}
.login-card{border:3px solid var(--ink);border-radius:11px;padding:30px;background:white;box-shadow:7px 7px 0 var(--ink);min-width:0}
.login-card h2{font-size:1.7rem}.login-card>h2::after{content:"";display:block;width:62px;height:6px;margin-top:12px;background:var(--lime);transform:skew(-15deg)}
.login-card>p{font-size:.9rem}.login-card .field{margin-bottom:16px}
.login-card .full{background:var(--lime);color:var(--ink)}
.demo{border-top:1.5px solid var(--line);padding-top:17px;margin-top:24px}.demo-users{gap:8px}.demo-users button{font-size:.72rem;box-shadow:2px 2px 0 var(--ink);padding:7px 8px}
.login-footer{color:#203318;font-weight:600;line-height:1.6;font-size:.72rem}
#registro-estudiante{padding-top:18px}#registro-estudiante[open]{margin-top:22px}
input,select,textarea{border:1.5px solid #aebaab;border-radius:6px;padding:11px 12px;background:#fdfefb;color:var(--ink);max-width:100%}
input:focus,select:focus,textarea:focus{border-color:var(--green)}
label{font-weight:650}.field small{line-height:1.5}textarea{min-height:110px}
/* Mascota original: encuadre de presentación, sin modificar sus píxeles. */
.mascot-scene{position:relative;isolation:isolate;pointer-events:none;min-width:0;overflow:hidden}
.mascot-backdrop{position:absolute;inset:12% -3% 2% 5%;background:var(--purple);clip-path:polygon(4% 25%,24% 28%,17% 5%,43% 28%,63% 0,67% 32%,100% 14%,82% 47%,100% 60%,76% 66%,85% 95%,50% 81%,21% 100%,22% 71%,0 67%,17% 48%);transform:rotate(-8deg);z-index:-1}
.mascot-frame{position:absolute;left:8%;top:0;width:84%;aspect-ratio:415/739;filter:drop-shadow(3px 0 0 #191c19) drop-shadow(-3px 0 0 #191c19) drop-shadow(0 -3px 0 #191c19) drop-shadow(0 4px 0 #191c19)}
.mascot-cutout{display:block;width:100%;height:100%;background:white var(--uvg-mascota) center top/100% auto no-repeat;clip-path:polygon(12% 11%,12% 4%,21% 5%,23% 2%,30% 5%,47% 4%,50% 0,56% 4%,62% 0,70% 1%,76% 5%,76% 11%,81% 11%,81% 18%,76% 24%,85% 35%,94% 38%,98% 36%,100% 42%,100% 54%,89% 56%,78% 50%,79% 71%,81% 85%,89% 93%,94% 96%,94% 100%,58% 100%,51% 97%,46% 100%,7% 100%,7% 94%,13% 85%,16% 70%,19% 51%,10% 56%,2% 54%,0 49%,0 42%,4% 42%,6% 38%,15% 39%,24% 30%,19% 26%,12% 25%,9% 20%,13% 18%,10% 14%)}
